from flask_sqlalchemy import SQLAlchemy
from flask import Flask, request, render_template_string
from datetime import date

app = Flask(__name__)

db = SQLAlchemy(app)


@app.route('/update_profile', methods=['POST'])
def update_profile():
    error_messages = []

    username = request.form.get('username')
    if username and len(username) > 20:
        error_messages.append('Username must be less than 20 characters')

    birthdate_str = request.form.get('birthdate')
    if birthdate_str:
        try:
            birthdate = date.fromisoformat(birthdate_str)
            age = ((date.today() - birthdate).days // 365)
            if age < 18 or age > 100:
                error_messages.append('Age must be between 18 and 100')
        except ValueError:
            error_messages.append('Invalid date format. Use YYYY-MM-DD.')
    else:
        error_messages.append('Birthdate is required')

    success = len(error_messages) == 0
    return render_template_string('''
        {% if success %}
            <p>You have been updated.</p>
        {% else %}
            {% for message in error_messages %}
                <p>{{ message }}</p>
            {% endfor %}
        {% endif %}
    ''', success=success, error_messages=error_messages)

