import os

def get_file_extensions(dir):
    exts = set()
    for root, dirs, files in os.walk(dir):
        for filename in files:
            basename, ext = os.path.splitext(filename)
            ext = ext.lower()
            if ext:
                exts.add(ext)
    return exts

