import java.io.UnsupportedEncodingException;
import java.nio.charset.Charset;
import java.util.Arrays;

public class SignalEncoder {
    private static final Charset CHARSET = Charset.forName("UTF-8");
    private static final int ADDRESS_WIDTH = 56;
    private static final int PLUGIN_TYPE_WIDTH = 10;

    public static byte[] encodeSignal(String type, String address, String data) {
        byte[] dataBytes = data.getBytes(CHARSET);
        if (dataBytes.length > 8192) {
            throw new IllegalArgumentException("Payload data too large!");
        }
        byte[] addrBytes = String.format("%1$" + ADDRESS_WIDTH + "s", address).getBytes();
        byte[] typeBytes = String.format("P%1$" + PLUGIN_TYPE_WIDTH + "s", type).getBytes();
        byte[] payload = new byte[addrBytes.length + typeBytes.length + dataBytes.length];
        System.arraycopy(addrBytes, 0, payload, 0, addrBytes.length);
        System.arraycopy(typeBytes, 0, payload, addrBytes.length, typeBytes.length);
        System.arraycopy(dataBytes, 0, payload, addrBytes.length + typeBytes.length, dataBytes.length);

        return payload;
    }

    public static byte[] encodeControlSignal(String action) {
        byte[] actionBytes = action.getBytes(CHARSET);
        if (actionBytes.length > 64) {
            throw new IllegalArgumentException("Control action too long!");
        }
        return actionBytes;
    }

    public static byte[] encodeFobData(String data) {
        byte[] dataBytes = data.getBytes(CHARSET);
        if (dataBytes.length > 64) {
            throw new IllegalArgumentException("Fob data too large!");
        }
        return dataBytes;
    }
}

