from pathlib import Path
import json

def walk(root):
    for dirpath, dirnames, filenames in os.walk(root):
        for filename in filenames:
            if filename.endswith('.zip'):
                zip_path = Path(dirpath, filename)
                md5_path = zip_path.with_suffix('.md5')

                with open(zip_path, 'rb') as f:
                    data = f.read()

                with open(md5_path, 'w') as f:
                    f.write(compute_md5(data))

import re
from flask import Flask, render_template

app = Flask(__name__)

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/edit', methods=['POST'])
def edit():
    name = bleach.clean(request.form.get('name'), tags=[])
    bio = bleach.clean(request.form.get('bio'), tags=['em', 'strong'])
    points = json.dumps(request.form.getlist('points'), separators=(',', ':'))
    tags_re = re.compile(r'\b(?P<tag>\w+)\b')
    tags = ',' + ','.join(tags_re.findall(request.form.get('tags', ''))) + ','
    html = f'<h1>{html.escape(name)}</h1>{html.escape(bio)}<ul>{points}</ul>Tags: {tags}'
    return html

